DECLARE
    actor_user_id UUID;
    repo_owner_id UUID;
BEGIN
    IF TG_TABLE_NAME = 'git_operations' THEN
        actor_user_id := NEW.actor_id;
    ELSE
        actor_user_id := NEW.author_id;
    END IF;

    SELECT owner_id INTO repo_owner_id
    FROM repositories
    WHERE id = NEW.repository_id;

    IF repo_owner_id IS NULL THEN
        RAISE EXCEPTION 'repository does not exist' USING ERRCODE = '23503';
    END IF;

    IF actor_user_id = repo_owner_id THEN
        RETURN NEW;
    END IF;

    IF EXISTS (
        SELECT 1 FROM repository_collaborators
        WHERE repository_id = NEW.repository_id AND user_id = actor_user_id
    ) THEN
        RETURN NEW;
    END IF;

    IF EXISTS (
        SELECT 1 FROM repository_team_members tm
        JOIN repository_teams t ON t.id = tm.team_id
        WHERE tm.repository_id = NEW.repository_id AND tm.user_id = actor_user_id
    ) THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'actor is not a member or collaborator of repository'
        USING ERRCODE = '23514';
END;

BEGIN
    IF TG_OP <> 'UPDATE' THEN
        RAISE EXCEPTION 'CI checkout jobs and cancellation tombstones are permanent';
    END IF;
    IF ROW(NEW.repository_id, NEW.job_id, NEW.owner_id, NEW.plan,
           NEW.issuer_token_id, NEW.credential_digest, NEW.expires_unix, NEW.created_at)
       IS DISTINCT FROM
       ROW(OLD.repository_id, OLD.job_id, OLD.owner_id, OLD.plan,
           OLD.issuer_token_id, OLD.credential_digest, OLD.expires_unix, OLD.created_at)
       OR (OLD.cancelled AND NOT NEW.cancelled)
       OR (OLD.revoked AND NOT NEW.revoked) THEN
        RAISE EXCEPTION 'CI checkout authority is immutable except monotonic cancellation/revocation';
    END IF;
    RETURN NEW;
END;

BEGIN
 IF EXISTS(SELECT 1 FROM operation_resolutions WHERE operation_id=OLD.id) AND (TG_OP='DELETE' OR NEW IS DISTINCT FROM OLD) THEN
  RAISE EXCEPTION 'resolved unknown operation history is immutable';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END

BEGIN
 IF (NEW.state,NEW.recovery_reason,NEW.storage_generation) IS DISTINCT FROM (OLD.state,OLD.recovery_reason,OLD.storage_generation) THEN
  NEW.incident_revision := OLD.incident_revision+1;
 ELSE NEW.incident_revision := OLD.incident_revision;
 END IF;
 RETURN NEW;
END

BEGIN
 IF EXISTS(SELECT 1 FROM operation_resolutions WHERE operation_id=NEW.operation_id) THEN RAISE EXCEPTION 'resolved unknown operation cannot publish events'; END IF;
 RETURN NEW;
END

DECLARE current_generation BIGINT;
BEGIN
 SELECT storage_generation INTO current_generation FROM repositories WHERE id=NEW.repository_id FOR SHARE;
 IF NEW.storage_generation IS DISTINCT FROM current_generation THEN RAISE EXCEPTION 'stale projection storage generation'; END IF;
 RETURN NEW;
END
